from typing import List

class Solution:
    def gameOfLife(self, board: List[List[int]]) -> None:
        m, n = len(board), len(board[0])
        next_live = set()
        for r in range(m):
            for c in range(n):
                live = 0
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < m and 0 <= nc < n:
                            live += board[nr][nc]
                if live == 3 or (board[r][c] == 1 and live == 2):
                    next_live.add((r, c))

        for r in range(m):
            for c in range(n):
                board[r][c] = 1 if (r, c) in next_live else 0

